def f(g):
    from collections import Counter
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    pts=[(i,j) for i,r in enumerate(g) for j,x in enumerate(r) if x!=bg]
    c=g[pts[0][0]][pts[0][1]]
    rows_={p[0] for p in pts}; cols_={p[1] for p in pts}
    n,m=len(g),len(g[0])
    if len(rows_)==1:
        return [[c if i==list(rows_)[0] else bg for j in range(m)] for i in range(n)]
    col=list(cols_)[0]
    return [[c if j==col else bg for j in range(m)] for i in range(n)]
